```kotlin
class OutboxRepository {
    suspend fun claimBatch(batchSize: Int): List<OutboxMessage> = newSuspendedTransaction {
        OutboxTable
            .select { (OutboxTable.state eq "pending") and (OutboxTable.scheduledAt lessEq Clock.System.now()) }
            .limit(batchSize)
            .forUpdate(ForUpdateOption.PostgreSQL.ForUpdate(mode = ForUpdateMode.SKIP_LOCKED))
            .map { it.toOutboxMessage() }
            .also { messages ->
                OutboxTable.update({ OutboxTable.id inList messages.map { it.id } }) {
                    it[state] = "processing"
                    it[updatedAt] = Clock.System.now().toJavaInstant()
                }
            }
    }

    suspend fun markSent(id: UUID) = updateState(id, "sent")
    suspend fun markFailed(id: UUID, error: String) { /* increment attempt, set error */ }
    suspend fun scheduleRetry(id: UUID, delayMs: Long) { /* set scheduled_at = now + delay, state = pending */ }
    suspend fun markDead(id: UUID) = updateState(id, "dead")
}
