2. **RetryStrategy.kt**:
```kotlin
class RetryStrategy(private val config: OutboxConfig) {
    fun calculateDelay(attempt: Int): Long {
        // Exponential backoff: base_delay * 2^attempt with jitter
        val exponentialDelay = config.retryBaseDelayMs * (1 shl attempt)
        val jitter = (0..(exponentialDelay / 4)).random()
        return (exponentialDelay + jitter).coerceAtMost(60_000L) // Max 1 minute
    }

    fun shouldRetry(attempt: Int, maxAttempts: Int): Boolean = attempt < maxAttempts
}
```

3. **MessageRouter.kt** - Glob pattern matching:
```kotlin
class MessageRouter(private val routes: List<RouteConfig>, private val destinations: Map<String, Destination>) {
    fun route(topic: String): RoutingResult? {
        val matchedRoute = routes.firstOrNull { matchesPattern(topic, it.topicPattern) }
        return matchedRoute?.let {
            RoutingResult(
                destination = destinations[it.destination]!!,
                routingKey = renderTemplate(it.routingKeyTemplate ?: topic, topic)
            )
        }
    }

    private fun matchesPattern(topic: String, pattern: String): Boolean {
        // Support glob: "*" matches any single segment, "**" matches multiple
        // "order.*" matches "order.created", "order.updated"
        // "*" matches everything
        val regex = pattern
            .replace(".", "\\.")
            .replace("**", ".*")
            .replace("*", "[^.]+")
            .toRegex()
        return regex.matches(topic)
    }
}

data class RoutingResult(val destination: Destination, val routingKey: String)
