```kotlin
class IdempotencyExtractor {
    fun extract(payload: JsonElement, jsonPath: String): Result<String> {
        return try {
            val jsonString = Json.encodeToString(payload)
            val documentContext = JsonPath.parse(jsonString)
            val value: Any = documentContext.read(jsonPath)
            Result.success(value.toString())
        } catch (e: PathNotFoundException) {
            Result.failure(ExtractionException("Path not found: $jsonPath"))
        } catch (e: Exception) {
            Result.failure(ExtractionException("Extraction failed: ${e.message}", e))
        }
    }
}

class ExtractionException(message: String, cause: Throwable? = null) : Exception(message, cause)
```

3. **InboxHandler.kt** - Coordination logic:
```kotlin
class InboxHandler(
    private val repository: InboxRepository,
    private val extractor: IdempotencyExtractor
) {
    suspend fun handle(source: String, sourceConfig: SourceConfig, payload: JsonElement): InboxHandlerResult {
        // Extract idempotency key
        val idempotencyKey = extractor.extract(payload, sourceConfig.idempotencyKeyPath)
            .getOrElse { return InboxHandlerResult.ExtractionFailed(it.message ?: "Unknown") }

        // Extract optional event type
        val eventType = sourceConfig.eventTypePath?.let {
            extractor.extract(payload, it).getOrNull()
        }

        // Build inbox message
        val message = InboxMessage(
            source = source,
            idempotencyKey = idempotencyKey,
            eventType = eventType,
            payload = payload
        )

        // Store with deduplication
        return when (val result = repository.store(message)) {
            is InboxResult.Stored -> InboxHandlerResult.Accepted(message.id)
            is InboxResult.Duplicate -> InboxHandlerResult.Duplicate
            is InboxResult.Error -> InboxHandlerResult.StorageFailed(result.message)
        }
    }
}

sealed class InboxHandlerResult {
    data class Accepted(val messageId: UUID) : InboxHandlerResult()
    data object Duplicate : InboxHandlerResult()
    data class ExtractionFailed(val reason: String) : InboxHandlerResult()
    data class StorageFailed(val reason: String) : InboxHandlerResult()
}
```

4. **InboxRoutes.kt** - Ktor route installer:
```kotlin
fun Application.configureInboxRoutes(config: InboxConfig, sources: Map<String, SourceConfig>, handler: InboxHandler) {
    routing {
        sources.forEach { (sourceName, sourceConfig) ->
            post("${config.basePath}${sourceConfig.path}") {
                val payload = try {
                    call.receive<JsonElement>()
                } catch (e: Exception) {
                    call.respond(HttpStatusCode.BadRequest, mapOf("error" to "Invalid JSON"))
                    return@post
                }

                when (val result = handler.handle(sourceName, sourceConfig, payload)) {
                    is InboxHandlerResult.Accepted -> 
                        call.respond(HttpStatusCode.OK, mapOf("messageId" to result.messageId.toString()))
                    is InboxHandlerResult.Duplicate -> 
                        call.respond(HttpStatusCode.OK, mapOf("status" to "duplicate"))
                    is InboxHandlerResult.ExtractionFailed -> 
                        call.respond(HttpStatusCode.BadRequest, mapOf("error" to result.reason))
                    is InboxHandlerResult.StorageFailed -> 
                        call.respond(HttpStatusCode.InternalServerError, mapOf("error" to "Storage failed"))
                }
            }
        }
    }
}
