        val result = repository.claimBatch(10)
        assertEquals(1, result.size)
        assertEquals(MessageState.Pending, result[0].state) // Original state before update
    }

    @Test
    fun `should_updateStateToProcessing_when_claimed`() = runBlocking {
        val id = insertTestMessage("pending")
        repository.claimBatch(10)
        val state = getMessageState(id)
        assertEquals("processing", state)
    }

    @Test
    fun `should_markSent_when_publishSucceeds`() = runBlocking {
        val id = insertTestMessage("processing")
        repository.markSent(id)
        assertEquals("sent", getMessageState(id))
    }

    @Test
    fun `should_incrementAttempt_when_markFailed`() = runBlocking {
        val id = insertTestMessage("processing")
        repository.markFailed(id, "Connection refused")
        val (state, attempt) = getMessageStateAndAttempt(id)
        assertEquals("failed", state)
        assertEquals(1, attempt)
    }

    @Test
    fun `should_scheduleRetry_when_retryRequested`() = runBlocking {
        val id = insertTestMessage("failed")
        repository.scheduleRetry(id, 5000)
        val (state, scheduledAt) = getStateAndScheduledAt(id)
        assertEquals("pending", state)
        assertTrue(scheduledAt > Clock.System.now())
    }

    @Test
    fun `should_notReturnSameMessage_when_concurrentClaims`() = runBlocking {
