3. **Create RetentionService.kt** in outbox-service module:
```kotlin
class RetentionService(
    private val config: RetentionConfig,
    private val outboxRepository: OutboxRepositoryInterface,
    private val inboxRepository: InboxRepositoryInterface,
    private val metrics: MetricsCollector
) {
    private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
    private val running = AtomicBoolean(false)

    private val completedStates = listOf("sent", "dead", "processed")

    fun start() {
        if (!config.enabled) return
        running.set(true)

        if (config.outbox.policy != RetentionPolicy.DISABLED) {
            scheduleCleanup("outbox", config.outbox) { cleanupOutbox(it) }
        }
        if (config.inbox.policy != RetentionPolicy.DISABLED) {
            scheduleCleanup("inbox", config.inbox) { cleanupInbox(it) }
        }
    }

    private fun scheduleCleanup(table: String, config: TableRetentionConfig, cleanup: suspend (TableRetentionConfig) -> Unit) {
        val interval = DurationParser.parse(config.cleanupInterval)
        scope.launch {
            while (running.get()) {
                try {
                    val startTime = System.nanoTime()
                    cleanup(config)
                    val duration = System.nanoTime() - startTime
                    metrics.recordCleanupDuration(table, duration)
                } catch (e: Exception) {
                    println("Cleanup error for $table: ${e.message}")
                }
                delay(interval.inWholeMilliseconds)
            }
        }
    }

    private suspend fun cleanupOutbox(config: TableRetentionConfig) {
        val deleted = when (config.policy) {
            RetentionPolicy.AGE -> {
                val cutoff = Clock.System.now() - DurationParser.parse(config.maxAge!!)
                deleteInBatches(config.batchSize) {
                    outboxRepository.deleteOlderThan(completedStates, cutoff)
                }
            }
            RetentionPolicy.COUNT -> {
                outboxRepository.deleteExceptMostRecent(completedStates, config.maxCount!!)
            }
            else -> 0
        }
        metrics.recordCleanupDeleted("outbox", deleted)
    }

    private suspend fun deleteInBatches(batchSize: Int, deleteFn: suspend () -> Int): Int {
        var totalDeleted = 0
        var deleted: Int
        do {
            deleted = deleteFn()
            totalDeleted += deleted
            if (deleted > 0) delay(10) // Small yield to prevent lock contention
        } while (deleted >= batchSize)
        return totalDeleted
    }
}
```

