class TransformEngine {
    // LRU cache for compiled expressions
    private val expressionCache = ConcurrentHashMap<String, Jsonata>()
    private val maxCacheSize = 1000

    fun evaluate(
        expression: String,
        payload: JsonElement,
        context: TransformContext,
        timeoutMs: Long = 100
    ): Result<JsonElement> = runCatching {
        val jsonata = expressionCache.getOrPut(expression) {
            Jsonata.jsonata(expression)
        }

        // Inject context variables
        val binding = mapOf(
            "messageId" to context.messageId.toString(),
            "topic" to context.topic,
            "attempt" to context.attempt,
            "timestamp" to context.timestamp.toString(),
            "source" to (context.source ?: "")
        )

        // Execute with timeout
        withTimeout(timeoutMs) {
            val result = jsonata.evaluate(payload.toString(), binding)
            Json.parseToJsonElement(result.toString())
        }
    }

    fun validateExpression(expression: String): Result<Unit> = runCatching {
        Jsonata.jsonata(expression)  // Throws if invalid
    }
}

data class TransformContext(
    val messageId: UUID,
    val topic: String,
    val attempt: Int,
    val timestamp: Instant,
    val source: String? = null
)
