```kotlin
private suspend fun processMessage(message: OutboxMessage) {
    val routingResult = router.route(message.topic) ?: run {
        repository.markDead(message.id)
        return
    }

    // Build transform context
    val context = TransformContext(
        messageId = message.id,
        topic = message.topic,
        attempt = message.attempt,
        timestamp = message.createdAt
    )

    // Apply transforms
    val transformResult = transformPipeline.transform(
        payload = message.payload,
        routeTransform = routingResult.routeTransform,
        destinationTransform = routingResult.destinationTransform,
        context = context
    )

    when (transformResult) {
        is TransformResult.Success -> {
            val transformedMessage = message.copy(payload = transformResult.payload)
            publishMessage(transformedMessage, routingResult)
        }
        is TransformResult.Error -> handlePublishFailure(message, Exception(transformResult.message))
        is TransformResult.DeadLetter -> repository.markDead(message.id)
    }
}
```

