fun Application.configureAdminRoutes(transformEngine: TransformEngine) {
    routing {
        route("/admin") {
            post("/transform/test") {
                val request = call.receive<TransformTestRequest>()

                // Validate expression first
                transformEngine.validateExpression(request.expression).getOrElse {
                    call.respond(HttpStatusCode.BadRequest, TransformTestResponse(
                        success = false,
                        error = "Invalid expression: ${it.message}"
                    ))
                    return@post
                }

                // Create mock context
                val context = TransformContext(
                    messageId = UUID.randomUUID(),
                    topic = request.mockTopic ?: "test.topic",
                    attempt = 1,
                    timestamp = Clock.System.now(),
                    source = request.mockSource
                )

                // Evaluate
                val result = transformEngine.evaluate(
                    expression = request.expression,
                    payload = request.payload,
                    context = context,
                    timeoutMs = request.timeoutMs ?: 100
                )

                result.fold(
                    onSuccess = { output ->
                        call.respond(TransformTestResponse(
                            success = true,
                            result = output,
                            context = context
                        ))
                    },
                    onFailure = { error ->
                        call.respond(HttpStatusCode.BadRequest, TransformTestResponse(
                            success = false,
                            error = error.message
                        ))
                    }
                )
            }
        }
    }
}
